import java.util.*;

public class Main {
    static int connectSticks(int[] sticks) {
        List<Integer> list = new ArrayList<>();
        for (int s : sticks) list.add(s);
        Collections.sort(list);
        int cost = 0;
        while (list.size() > 1) {
            int a = list.remove(0), b = list.remove(0);
            int combined = a + b;
            cost += combined;
            list.add(combined);
            Collections.sort(list);              // re-sort from scratch every round
        }
        return cost;
    }
}

