#include <bits/stdc++.h>
using namespace std;

int connectSticks(vector<int> sticks) {
    sort(sticks.begin(), sticks.end());
    int cost = 0;
    while (sticks.size() > 1) {
        int a = sticks[0], b = sticks[1];
        sticks.erase(sticks.begin(), sticks.begin() + 2);
        int combined = a + b;
        cost += combined;
        sticks.push_back(combined);
        sort(sticks.begin(), sticks.end());        // re-sort from scratch every round
    }
    return cost;
}

