import java.util.*;

public class Main {
    static int connectSticks(int[] sticks) {
        PriorityQueue<Integer> heap = new PriorityQueue<>();
        for (int s : sticks) heap.offer(s);
        int cost = 0;
        while (heap.size() > 1) {
            int a = heap.poll(), b = heap.poll();
            int combined = a + b;
            cost += combined;
            heap.offer(combined);                 // O(log n), no full re-sort
        }
        return cost;
    }
}

