#include <bits/stdc++.h>
using namespace std;

int connectSticks(vector<int>& sticks) {
    priority_queue<int, vector<int>, greater<int>> heap(sticks.begin(), sticks.end());
    int cost = 0;
    while (heap.size() > 1) {
        int a = heap.top(); heap.pop();
        int b = heap.top(); heap.pop();
        int combined = a + b;
        cost += combined;
        heap.push(combined);                    // O(log n), no full re-sort
    }
    return cost;
}
